)

// Inviter is a compile-time interface check. Any handler that depends on the
// identityclient need only declare this interface locally.
type Inviter interface {
	Invite(ctx context.Context, p identityclient.InviteParams) (*userv1.User, string, bool, error)
	Close() error
}

// Verify that *identityclient.Client satisfies Inviter at compile time.
var _ Inviter = (*identityclient.Client)(nil)

func TestNewClientInvalidAddr(t *testing.T) {
	// grpc.NewClient is lazy — it does not dial immediately. An empty address
	// is actually accepted by the gRPC library and fails on the first RPC.
	// We verify that NewClient returns a non-nil client for a syntactically
	// valid but unreachable address, and that Close succeeds.
	c, err := identityclient.NewClient("localhost:1", mtls.Config{})
	require.NoError(t, err)
	require.NotNil(t, c)
	require.Equal(t, mtls.ModeInsecure, c.Mode, "empty mtls.Config should produce insecure transport")
	require.NoError(t, c.Close())
}

func TestNewClient_PartialMTLSConfig_Errors(t *testing.T) {
	// Half-configured mTLS is the dangerous footgun: it must fail loudly
	// at NewClient rather than silently fall back to insecure.
	_, err := identityclient.NewClient("localhost:1", mtls.Config{
		CertFile: "/some/cert",
	})
	require.Error(t, err)
}

// TestContextWithBearerForTenant_UsesTenantArg asserts that the cross-org
// helper puts the explicit tenantID into x-tenant-id metadata rather than
// the caller's JWT org (claims.OrgID).
func TestContextWithBearerForTenant_UsesTenantArg(t *testing.T) {
	// Arrange: create a context that has claims whose OrgID is the CALLER's
	// home org — NOT the target org.
	callerHomeOrg := "caller-home-org-uuid"
	targetOrg := "target-org-uuid"

	claims := auth.Claims{
		Subject: "platform-admin-user",
		OrgID:   callerHomeOrg,
		Roles:   []string{"admin"},
	}
	ctx := auth.ClaimsIntoContext(context.Background(), claims)

	// Act: call the new helper with the target org as the explicit tenant.
	outCtx := identityclient.ContextWithBearerForTenant(ctx, "Bearer token123", targetOrg)

	// Assert: outgoing metadata must carry x-tenant-id == targetOrg.
	md, ok := metadata.FromOutgoingContext(outCtx)
	require.True(t, ok, "outgoing metadata must be set")

	tenantVals := md.Get(auth.HeaderTenantID)
	require.Len(t, tenantVals, 1, "exactly one x-tenant-id value expected")
	require.Equal(t, targetOrg, tenantVals[0],
		"x-tenant-id must be the explicit tenantID arg, NOT the caller's JWT org %q", callerHomeOrg)
}

func TestInviteReturnsErrorOnUnreachableServer(t *testing.T) {
	c, err := identityclient.NewClient("localhost:1", mtls.Config{})
	require.NoError(t, err)
	defer c.Close() //nolint:errcheck

	_, _, _, err = c.Invite(context.Background(), identityclient.InviteParams{
		Email:       "test@example.com",
		DisplayName: "Test User",
		OrgID:       uuid.New(),
	})
	require.Error(t, err, "expected error when server is unreachable")
}

// TestRemoveFromOrgReturnsErrorOnUnreachableServer pins the new
// RemoveFromOrg wrapper: it forwards to UserService.RemoveFromOrg and
// surfaces the gRPC error when the server is unreachable.
func TestRemoveFromOrgReturnsErrorOnUnreachableServer(t *testing.T) {
	c, err := identityclient.NewClient("localhost:1", mtls.Config{})
	require.NoError(t, err)
	defer c.Close() //nolint:errcheck

	_, err = c.RemoveFromOrg(context.Background(), uuid.NewString())
	require.Error(t, err, "expected error when server is unreachable")
}

// TestRemoveFromOrgFreeEmailReturnsErrorOnUnreachableServer mirrors
// TestRemoveFromOrgReturnsErrorOnUnreachableServer for the opt-in
// email-freeing variant (Finding 2 fix) — same wiring, same error
// propagation, distinct method so admin-bff's platform-delete fan-out and
// the shipped single-org endpoint can never accidentally share a call site.
func TestRemoveFromOrgFreeEmailReturnsErrorOnUnreachableServer(t *testing.T) {
	c, err := identityclient.NewClient("localhost:1", mtls.Config{})
	require.NoError(t, err)
	defer c.Close() //nolint:errcheck

	_, err = c.RemoveFromOrgFreeEmail(context.Background(), uuid.NewString())
	require.Error(t, err, "expected error when server is unreachable")
}

// TestNewClient_WiresDeadlineInterceptor proves NewClient dials with
// grpcclient.DialOptions installed: a call whose context carries no
// deadline of its own must still be cut off, because the dial-site tier
// (overridden here via grpcclient.WithTier to keep the test fast) arms one.
// Against a listener that accepts the TCP connection but never speaks gRPC,
// an RPC with no client-side deadline at all would hang indefinitely; one
// with the interceptor installed returns DeadlineExceeded quickly.
func TestNewClient_WiresDeadlineInterceptor(t *testing.T) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	defer ln.Close() //nolint:errcheck

	go func() {
		for {
			conn, acceptErr := ln.Accept()
			if acceptErr != nil {
				return
			}
			defer conn.Close() //nolint:errcheck
		}
	}()

	c, err := identityclient.NewClient(ln.Addr().String(), mtls.Config{})
	require.NoError(t, err)
	defer c.Close() //nolint:errcheck

	ctx := grpcclient.WithTier(context.Background(), 50*time.Millisecond)

	type result struct {
		err error
	}
	resCh := make(chan result, 1)
	start := time.Now()
	go func() {
		_, _, _, callErr := c.Invite(ctx, identityclient.InviteParams{
			Email:       "a@example.com",
			DisplayName: "A",
			OrgID:       uuid.New(),
		})
		resCh <- result{err: callErr}
	}()

	select {
	case res := <-resCh:
		elapsed := time.Since(start)
		assert.Less(t, elapsed, 2*time.Second, "call should be cut off by the armed deadline, not hang")
		require.Error(t, res.err)
		st, ok := status.FromError(res.err)
		require.True(t, ok, "expected a gRPC status error, got %v", res.err)
		assert.Equal(t, codes.DeadlineExceeded, st.Code(), "no client-side deadline was armed: DialOptions is not wired")
	case <-time.After(2 * time.Second):
		t.Fatal("Invite did not return within 2s — no deadline was armed, DialOptions is not wired")
	}
}


