// TestContextWithBearer_ForwardsRequestID pins the header-propagation
// contract from platform/proto/CONVENTIONS.md §1: every hop must forward
// x-request-id. The chi RequestID middleware on the inbound HTTP request
// seeds middleware.RequestIDKey in the request context; ContextWithBearer
// must lift that into the outgoing gRPC metadata so identity-svc (and the
// hand-authored admin-bff-identity-svc-apikey pact, which asserts
// x-request-id) sees it. The gRPC client has no separate forwarding
// interceptor, so ContextWithBearer is the only injection point.
func TestContextWithBearer_ForwardsRequestID(t *testing.T) {
	// Seed the chi request id (set by middleware.RequestID on the inbound request).
	ctx := context.WithValue(context.Background(), middleware.RequestIDKey, "req-abc-123")
	ctx = auth.ClaimsIntoContext(ctx, auth.Claims{
		Subject: "user-1",
		OrgID:   "org-1",
	})

	out := ContextWithBearer(ctx, "Bearer tok")
	md, ok := metadata.FromOutgoingContext(out)
	require.True(t, ok)
	assert.Equal(t, []string{"req-abc-123"}, md.Get(auth.HeaderRequestID))
}

// TestContextWithBearer_NoRequestIDWhenAbsent confirms the helper does not
// fabricate an x-request-id when the inbound request never carried one — it
// must only forward what chi actually set.
func TestContextWithBearer_NoRequestIDWhenAbsent(t *testing.T) {
	ctx := auth.ClaimsIntoContext(context.Background(), auth.Claims{
		Subject: "user-1",
		OrgID:   "org-1",
	})

	out := ContextWithBearer(ctx, "Bearer tok")
	md, _ := metadata.FromOutgoingContext(out)
	assert.Empty(t, md.Get(auth.HeaderRequestID))
}


