// Package identityclient is a thin wrapper over the identity-svc gRPC
// UserServiceClient. admin-bff uses it from invite handlers to provision new
// users through identity-svc.
//
// Transport credentials are decided by the caller via mtls.Config: with
// the three MTLS_*_FILE env vars set, we dial with mTLS; otherwise the
// helper returns insecure credentials (current state — Vault PKI rollout
// is staged).
package identityclient

import (
	"context"
	"time"

	"github.com/go-chi/chi/v5/middleware"
	"github.com/google/uuid"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/grpcclient"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/mtls"
	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	apikeyv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/identity/api_key/v1"
	userv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/identity/user/v1"
)

// Client wraps a gRPC connection to identity-svc.
type Client struct {
	conn    *grpc.ClientConn
	api     userv1.UserServiceClient
	apikeys apikeyv1.ApiKeyServiceClient
	// Mode reports whether the underlying transport is mTLS or insecure
	// — exposed so callers can log the posture once at startup.
	Mode mtls.Mode
}

// InviteParams carries the parameters needed to invite a new user.
type InviteParams struct {
	Email       string
	DisplayName string
	OrgID       uuid.UUID
}

// NewClient dials identity-svc at addr with the given mTLS posture.
// Pass an empty mtls.Config{} to get insecure transport (current dev
// default); set CertFile/KeyFile/CAFile to dial with mTLS. Partial
// configuration is a hard error.
func NewClient(addr string, mtlsCfg mtls.Config) (*Client, error) {
	creds, mode, err := mtls.BuildTransportCredentials(mtlsCfg)
	if err != nil {
		return nil, err
	}
	// P0-05: fail closed instead of silently dialing plaintext.
	if err := mtls.EnforceMode(mode); err != nil {
		return nil, err
	}
	conn, err := grpc.NewClient(addr, grpcclient.DialOptions(grpcclient.TierDefault, grpc.WithTransportCredentials(creds))...)
	if err != nil {
		return nil, err
	}
	return &Client{
		conn:    conn,
		api:     userv1.NewUserServiceClient(conn),
		apikeys: apikeyv1.NewApiKeyServiceClient(conn),
		Mode:    mode,
	}, nil
}

// Close releases the underlying gRPC connection.
func (c *Client) Close() error {
	return c.conn.Close()
}

// Invite provisions a user in identity-svc and returns the created (or
// re-attached) User, the temporary password generated by the IdP, and a flag
// indicating whether the IdP already had a user with this email.
//
// alreadyExisted=true means identity-svc's healInviteOrphan path matched an
// existing IdP user (typically a member of a different org being invited into
// a new one). In that case tempPassword is always empty — the user signs in
// with their existing credentials and the admin UI must NOT render the
// temp-password banner.
//
// East-west auth: until mTLS + service-account JWTs land, the caller's
// inbound bearer token is forwarded as the gRPC `authorization` metadata
// entry. The user JWT must include `identity-svc` in its `aud` claim
// (handled by the audience-identity-svc-via-shell mapper in the realm
// export). When mTLS is wired, this forwarding is replaced by a per-hop
// service-account JWT minted by admin-bff.
func (c *Client) Invite(ctx context.Context, p InviteParams) (*userv1.User, string, bool, error) {
	resp, err := c.api.Invite(ctx, &userv1.InviteRequest{
		Email:       p.Email,
		DisplayName: p.DisplayName,
		OrgId:       &commonv1.OrgID{Value: p.OrgID.String()},
	})
	if err != nil {
		return nil, "", false, err
	}
	return resp.GetUser(), resp.GetTempPassword(), resp.GetAlreadyExisted(), nil
}

// ListUsersParams carries the cursor + limit for paginating users.
type ListUsersParams struct {
	Cursor string
	Limit  int32
}

// ListUsersResult mirrors the gRPC ListResponse: the page of users +
// next cursor (empty when no more pages exist).
type ListUsersResult struct {
	Users      []*userv1.User
	NextCursor string
}

// ListUsers pages through users in the caller's tenant. Forwards the
// caller's bearer + x-* headers via ContextWithBearer so identity-svc
// can set the RLS GUC.
func (c *Client) ListUsers(ctx context.Context, p ListUsersParams) (*ListUsersResult, error) {
	resp, err := c.api.List(ctx, &userv1.ListRequest{
		Cursor: p.Cursor,
		Limit:  p.Limit,
	})
	if err != nil {
		return nil, err
	}
	return &ListUsersResult{
		Users:      resp.GetUsers(),
		NextCursor: resp.GetNextCursor(),
	}, nil
}

// UpdateUserParams carries the editable user fields. display_name is
// the only mutable field today; status flows through Activate/Suspend
// and role/tenant edits live in org-svc.
type UpdateUserParams struct {
	UserID      string
	DisplayName string
}

// UpdateUser edits the mutable fields on a user and returns the
// post-image. Forwards the caller's bearer + x-* headers so identity-svc
// can drive RLS + audit attribution.
func (c *Client) UpdateUser(ctx context.Context, p UpdateUserParams) (*userv1.User, error) {
	resp, err := c.api.Update(ctx, &userv1.UpdateRequest{
		UserId:      p.UserID,
		DisplayName: p.DisplayName,
	})
	if err != nil {
		return nil, err
	}
	return resp.GetUser(), nil
}

// SuspendUser flips status → DISABLED and returns the post-image.
// identity-svc emits the user_suspended audit event in the same tx.
func (c *Client) SuspendUser(ctx context.Context, userID string) (*userv1.User, error) {
	resp, err := c.api.Suspend(ctx, &userv1.SuspendRequest{UserId: userID})
	if err != nil {
		return nil, err
	}
	return resp.GetUser(), nil
}

// ReactivateUser flips status → ACTIVE and returns the post-image. Used
// by the Members surface to undo a Suspend. Same RPC the activation
// flow uses on first-login password change; identity-svc decides the
// audit subject based on the resulting status.
func (c *Client) ReactivateUser(ctx context.Context, userID string) (*userv1.User, error) {
	resp, err := c.api.Activate(ctx, &userv1.ActivateRequest{UserId: userID})
	if err != nil {
		return nil, err
	}
	return resp.GetUser(), nil
}

// RemoveFromOrg removes a user from the caller's org in identity-svc.
// userID is the Keycloak sub; identity-svc resolves it to the org-scoped
// identity.users row internally. Returns keycloakDisabled=true when this
// was the user's last org and the Keycloak login was disabled; false when
// the account stays active for their other org(s). Surfaces the gRPC
// error verbatim so the handler can translate it. Forwards the caller's
// bearer + x-* headers via the ctx the handler pins.
func (c *Client) RemoveFromOrg(ctx context.Context, userID string) (bool, error) {
	resp, err := c.api.RemoveFromOrg(ctx, &userv1.RemoveFromOrgRequest{UserId: userID})
	if err != nil {
		return false, err
	}
	return resp.GetKeycloakDisabled(), nil
}

// RemoveFromOrgFreeEmail is the opt-in variant of RemoveFromOrg used ONLY by
// admin-bff's platform-delete fan-out (PlatformUsersHandler.Delete step 4,
// via the PlatformOrgRemover interface). It sets
// RemoveFromOrgRequest.free_email=true so identity-svc rewrites the row's
// email to a sentinel in the SAME transaction that flips it DISABLED,
// freeing the original (org_id, email) pair for a future re-invite — the
// fix for Finding 2 in the review-fixes ledger.
//
// The shipped single-org endpoint (OrgUsersHandler.RemoveUserFromOrg, via
// the separate IdentityOrgRemover interface) MUST keep calling the plain
// RemoveFromOrg above so its behaviour stays byte-identical (R23's scope
// boundary) — the two interfaces exist precisely so the two call sites can
// never accidentally share wiring.
func (c *Client) RemoveFromOrgFreeEmail(ctx context.Context, userID string) (bool, error) {
	resp, err := c.api.RemoveFromOrg(ctx, &userv1.RemoveFromOrgRequest{UserId: userID, FreeEmail: true})
	if err != nil {
		return false, err
	}
	return resp.GetKeycloakDisabled(), nil
}

// ListPlatformUsersParams carries the optional filters for the platform-wide
// browse. Zero values disable each filter.
type ListPlatformUsersParams struct {
	Query          string
	Status         userv1.UserStatus
	KeycloakUserID string
	Cursor         string
	Limit          int32
}

// ListPlatformUsersResult is the page plus its continuation cursor.
type ListPlatformUsersResult struct {
	Users      []*userv1.PlatformUser
	NextCursor string
}

// ListPlatformUsers reads the cross-org, person-grouped user browse.
// identity-svc gates this on the caller's "admin" realm role.
func (c *Client) ListPlatformUsers(
	ctx context.Context,
	p ListPlatformUsersParams,
) (*ListPlatformUsersResult, error) {
	resp, err := c.api.ListPlatformUsers(ctx, &userv1.ListPlatformUsersRequest{
		Query:          p.Query,
		Status:         p.Status,
		KeycloakUserId: p.KeycloakUserID,
		Cursor:         p.Cursor,
		Limit:          p.Limit,
	})
	if err != nil {
		return nil, err
	}
	return &ListPlatformUsersResult{
		Users:      resp.GetUsers(),
		NextCursor: resp.GetNextCursor(),
	}, nil
}

// ResetPassword sets a temporary password for userID (a Keycloak sub) and
// returns it for one-time display. The caller MUST NOT log the result.
func (c *Client) ResetPassword(ctx context.Context, userID string) (string, error) {
	resp, err := c.api.ResetPassword(ctx, &userv1.ResetPasswordRequest{UserId: userID})
	if err != nil {
		return "", err
	}
	return resp.GetTemporaryPassword(), nil
}

// DeleteAccount purges userID's Keycloak account — the terminal step of the
// platform-delete fan-out. Returns whether this call performed the deletion
// (false means it was already absent).
func (c *Client) DeleteAccount(ctx context.Context, userID string) (bool, error) {
	resp, err := c.api.DeleteAccount(ctx, &userv1.DeleteAccountRequest{UserId: userID})
	if err != nil {
		return false, err
	}
	return resp.GetKeycloakDeleted(), nil
}

// IsPlatformAdmin reports whether userID (a Keycloak sub) holds the realm
// "admin" role. Mutates nothing. admin-bff's platform-delete fan-out calls
// this as a PRE-FLIGHT, before mutating any org membership, so a target
// holding the admin role is refused before the fan-out starts rather than
// only at the terminal DeleteAccount step — see PlatformUsersHandler.Delete.
func (c *Client) IsPlatformAdmin(ctx context.Context, userID string) (bool, error) {
	resp, err := c.api.IsPlatformAdmin(ctx, &userv1.IsPlatformAdminRequest{UserId: userID})
	if err != nil {
		return false, err
	}
	return resp.GetIsAdmin(), nil
}

// TwoFAStatus is the wire shape admin-bff returns to admin-mfe.
type TwoFAStatus struct {
	Enrolled      bool
	SetupRequired bool
}

// Get2FAStatus fetches second-factor enrollment state from identity-svc.
func (c *Client) Get2FAStatus(ctx context.Context, userID string) (*TwoFAStatus, error) {
	resp, err := c.api.Get2FAStatus(ctx, &userv1.Get2FAStatusRequest{UserId: userID})
	if err != nil {
		return nil, err
	}
	return &TwoFAStatus{
		Enrolled:      resp.GetEnrolled(),
		SetupRequired: resp.GetSetupRequired(),
	}, nil
}

// Require2FASetup adds CONFIGURE_TOTP to the user's required actions.
func (c *Client) Require2FASetup(ctx context.Context, userID string) error {
	_, err := c.api.Require2FASetup(ctx, &userv1.Require2FASetupRequest{UserId: userID})
	return err
}

// Reset2FA removes every OTP/WebAuthn credential from the user and
// returns the count removed (zero is a legitimate idempotent success).
func (c *Client) Reset2FA(ctx context.Context, userID string) (uint32, error) {
	resp, err := c.api.Reset2FA(ctx, &userv1.Reset2FARequest{UserId: userID})
	if err != nil {
		return 0, err
	}
	return resp.GetCredentialsRemoved(), nil
}

// ---------------------------------------------------------------------------
// ApiKeyService — admin-issued machine credentials
// ---------------------------------------------------------------------------

// IssueApiKeyParams carries the parameters needed to mint a new API key.
// ExpiresAt is optional — a nil pointer means the key never expires.
type IssueApiKeyParams struct {
	Name        string
	AccessLevel apikeyv1.ApiKeyAccessLevel
	ExpiresAt   *time.Time
}

// IssueApiKey mints a new API key in identity-svc. The returned response
// carries the post-image plus the one-time plaintext secret. ctx already
// carries the caller's bearer + x-* headers via ContextWithBearer.
func (c *Client) IssueApiKey(ctx context.Context, p IssueApiKeyParams) (*apikeyv1.IssueResponse, error) {
	req := &apikeyv1.IssueRequest{Name: p.Name, AccessLevel: p.AccessLevel}
	if p.ExpiresAt != nil {
		req.ExpiresAt = timestamppb.New(*p.ExpiresAt)
	}
	return c.apikeys.Issue(ctx, req)
}

// ListApiKeys returns every API key in the caller's tenant. RLS at
// identity-svc enforces the cross-tenant boundary from x-tenant-id.
func (c *Client) ListApiKeys(ctx context.Context) (*apikeyv1.ListResponse, error) {
	return c.apikeys.List(ctx, &apikeyv1.ListRequest{})
}

// RotateApiKey re-issues the secret for an existing key, returning the
// post-image plus the new one-time plaintext secret.
func (c *Client) RotateApiKey(ctx context.Context, id string) (*apikeyv1.RotateResponse, error) {
	return c.apikeys.Rotate(ctx, &apikeyv1.RotateRequest{Id: id})
}

// RevokeApiKey disables a key permanently. Idempotent at identity-svc
// when the key is already revoked.
func (c *Client) RevokeApiKey(ctx context.Context, id string) error {
	_, err := c.apikeys.Revoke(ctx, &apikeyv1.RevokeRequest{Id: id})
	return err
}

// LookupUserSummary is the slim shape admin-bff returns to admin-mfe
// when resolving workspace owners — display_name + email are enough
// for the Owner column. Full Users come back via ListUsers.
//
// ID is the identity-svc internal UUIDv7. KeycloakUserID is the Keycloak
// sub claim (UUID v4) used by every membership lookup keyed on
// claims.Subject — org.memberships.user_id stores the Keycloak UUID,
// not the identity-svc UUIDv7, so the workspace switcher's
// ListMembershipsByUser(claims.Subject) call can find the rows.
// Callers that wire a user into a membership row MUST use
// KeycloakUserID; callers that resolve a tenant's created_by_user_id
// or display the user in a non-membership context use ID.
type LookupUserSummary struct {
	ID             string
	KeycloakUserID string
	Email          string
	DisplayName    string
	// OrgID is the user's owning organization (identity.users.org_id). It
	// is the defense-in-depth signal the admin-bff AddMember handler uses
	// to confirm a user belongs to a workspace's parent org before
	// attaching a membership row: even if a lookup were to return a
	// cross-org row, the handler can reject on OrgID mismatch. Zero-value
	// uuid.UUID when the upstream did not populate org_id.
	OrgID uuid.UUID
}

// LookupUserByEmail resolves a single email to a user within the
// caller's tenant. Returns (nil, gRPC NotFound) when no user matches.
// Phase 4g — backs the admin-mfe "Add member by email" flow.
func (c *Client) LookupUserByEmail(ctx context.Context, email string) (*LookupUserSummary, error) {
	resp, err := c.api.LookupUserByEmail(ctx, &userv1.LookupUserByEmailRequest{Email: email})
	if err != nil {
		return nil, err
	}
	u := resp.GetUser()
	return &LookupUserSummary{
		ID:             u.GetId(),
		KeycloakUserID: u.GetKeycloakUserId(),
		Email:          u.GetEmail(),
		DisplayName:    u.GetDisplayName(),
	}, nil
}

// LookupUsersByIDs batch-resolves user_ids via identity-svc. Unknown /
// cross-tenant ids are silently dropped — callers must not assume the
// response length matches the request length. Empty input returns
// (nil, nil) without a round-trip. Phase 4e.
//
// userIDs are identity.users.id (UUIDv7). To resolve identifiers
// stored as Keycloak subs (org.memberships.user_id,
// org.tenants.created_by_user_id) use LookupUsersByKeycloakIDs instead.
func (c *Client) LookupUsersByIDs(ctx context.Context, userIDs []string) ([]LookupUserSummary, error) {
	if len(userIDs) == 0 {
		return nil, nil
	}
	resp, err := c.api.LookupUsersByIds(ctx, &userv1.LookupUsersByIdsRequest{UserIds: userIDs})
	if err != nil {
		return nil, err
	}
	out := make([]LookupUserSummary, 0, len(resp.GetUsers()))
	for _, u := range resp.GetUsers() {
		out = append(out, LookupUserSummary{
			ID:             u.GetId(),
			KeycloakUserID: u.GetKeycloakUserId(),
			Email:          u.GetEmail(),
			DisplayName:    u.GetDisplayName(),
		})
	}
	return out, nil
}

// LookupUsersByKeycloakIDs is the Keycloak-sub-keyed batch lookup.
// Admin-bff calls this when resolving identifiers stored as Keycloak
// subs (org.memberships.user_id, org.tenants.created_by_user_id) —
// LookupUsersByIDs cannot resolve those because identity.users.id is
// the internal UUIDv7, not the Keycloak sub. Same omission contract:
// unknown / cross-tenant ids are silently dropped from the response.
// Empty input returns (nil, nil) without a round-trip.
func (c *Client) LookupUsersByKeycloakIDs(ctx context.Context, keycloakIDs []string) ([]LookupUserSummary, error) {
	if len(keycloakIDs) == 0 {
		return nil, nil
	}
	resp, err := c.api.LookupUsersByKeycloakIds(ctx, &userv1.LookupUsersByKeycloakIdsRequest{KeycloakUserIds: keycloakIDs})
	if err != nil {
		return nil, err
	}
	out := make([]LookupUserSummary, 0, len(resp.GetUsers()))
	for _, u := range resp.GetUsers() {
		out = append(out, LookupUserSummary{
			ID:             u.GetId(),
			KeycloakUserID: u.GetKeycloakUserId(),
			Email:          u.GetEmail(),
			DisplayName:    u.GetDisplayName(),
			OrgID:          parseOrgID(u.GetOrgId().GetValue()),
		})
	}
	return out, nil
}

// parseOrgID converts the proto OrgID string into a uuid.UUID, returning
// the zero value (uuid.Nil) on empty/invalid input. The AddMember
// parent-org guard treats a zero OrgID as "no match" (fail closed) when
// comparing against a resolved parent org id.
func parseOrgID(s string) uuid.UUID {
	if s == "" {
		return uuid.Nil
	}
	id, err := uuid.Parse(s)
	if err != nil {
		return uuid.Nil
	}
	return id
}

// Lookup2FAStatusesByIds forwards to identity-svc batched 2FA read.
// Empty input short-circuits. Phase 4j.
func (c *Client) Lookup2FAStatusesByIds(
	ctx context.Context, userIDs []string,
) (map[string]TwoFAStatus, error) {
	if len(userIDs) == 0 {
		return map[string]TwoFAStatus{}, nil
	}
	resp, err := c.api.Lookup2FAStatusesByIds(ctx, &userv1.Lookup2FAStatusesByIdsRequest{UserIds: userIDs})
	if err != nil {
		return nil, err
	}
	out := make(map[string]TwoFAStatus, len(resp.GetStatuses()))
	for id, st := range resp.GetStatuses() {
		out[id] = TwoFAStatus{
			Enrolled:      st.GetEnrolled(),
			SetupRequired: st.GetSetupRequired(),
		}
	}
	return out, nil
}

// LookupKeycloakProfilesByIDs batch-resolves Keycloak user UUIDs to display
// names via identity-svc's LookupKeycloakProfilesByIds RPC, which proxies to
// the Keycloak Admin API. Platform-admin accounts live only in the Keycloak
// realm and have no identity.users row, so the table-backed lookups cannot
// resolve them — this RPC uses the Keycloak Admin API directly.
//
// Returns a map of Keycloak user UUID → display name. IDs not found in
// Keycloak are absent from the map (callers fall back to empty string).
// Empty input returns (nil, nil) without a round-trip.
//
// bearer is the inbound HTTP Authorization header forwarded east-west for
// mTLS + service-account JWT. It is injected into gRPC metadata directly
// so identity-svc's auth interceptor can validate it.
func (c *Client) LookupKeycloakProfilesByIDs(ctx context.Context, bearer string, ids []string) (map[string]string, error) {
	if len(ids) == 0 {
		return nil, nil
	}
	// Build outgoing gRPC metadata with the forwarded bearer.
	// We use AppendToOutgoingContext rather than ContextWithBearer because
	// this call originates from a platform-admin HTTP request whose JWT may
	// lack the standard org-membership claims expected by ContextWithBearer.
	grpcCtx := metadata.AppendToOutgoingContext(ctx, AuthorizationKey, bearer)
	resp, err := c.api.LookupKeycloakProfilesByIds(grpcCtx, &userv1.LookupKeycloakProfilesByIdsRequest{Ids: ids})
	if err != nil {
		return nil, err
	}
	out := make(map[string]string, len(resp.GetProfiles()))
	for _, p := range resp.GetProfiles() {
		if p.GetId() != "" {
			out[p.GetId()] = p.GetDisplayName()
		}
	}
	return out, nil
}

// AuthorizationKey is the gRPC metadata key (lowercase) that carries the
// bearer token forwarded from the inbound HTTP request.
const AuthorizationKey = "authorization"

// ContextWithBearerForTenant is like ContextWithBearer but uses the
// supplied tenantID for x-tenant-id instead of the caller's JWT org.
// Required for cross-org admin operations (e.g. platform admin
// inviting a user into a different org): identity-svc's RLS gates
// writes by row tenancy, so the GUC must match the row's org_id.
// Authorization is gated upstream (RBAC scope + realm role checks
// at the BFF; JWT aud/azp check at the service hop — mTLS is not enforced
// on that hop: MTLS_*_FILE is unset and OMNICORE_ALLOW_INSECURE_MTLS
// defaults true; #2380 tracks wiring it).
//
// It forwards the inbound bearer as gRPC authorization, x-tenant-id from
// the supplied tenantID, x-user-id and x-actor-type from the JWT claims
// (so audit attribution continues to name the actual caller), and
// x-request-id lifted from the chi RequestID middleware when the inbound
// request carried one (CONVENTIONS.md §1 — every hop propagates the
// request id). It does not forward x-trace-id; trace context is OTel's
// concern, propagated by the observability interceptors, not here.
func ContextWithBearerForTenant(ctx context.Context, bearer, tenantID string) context.Context {
	pairs := []string{}
	if bearer != "" {
		pairs = append(pairs, AuthorizationKey, bearer)
	}
	if tenantID != "" {
		pairs = append(pairs, auth.HeaderTenantID, tenantID)
	}
	if c, ok := auth.ClaimsFromContext(ctx); ok {
		if c.Subject != "" {
			pairs = append(pairs, auth.HeaderUserID, c.Subject)
		}
		pairs = append(pairs, auth.HeaderActorType, "user")
	}
	if rid := middleware.GetReqID(ctx); rid != "" {
		pairs = append(pairs, auth.HeaderRequestID, rid)
	}
	if len(pairs) == 0 {
		return ctx
	}
	return metadata.AppendToOutgoingContext(ctx, pairs...)
}

// ContextWithBearer returns ctx with the inbound HTTP request's bearer token
// set as the gRPC `authorization` metadata entry, AND the platform x-* headers
// minted from the request: x-tenant-id, x-user-id and x-actor-type from the
// validated JWT claims attached to ctx by the auth middleware, plus
// x-request-id lifted from the chi RequestID middleware when the inbound
// request carried one (CONVENTIONS.md §1 — every hop propagates the request
// id; the gRPC client has no separate forwarding interceptor, so this is the
// injection point). It does not forward x-trace-id; trace context is OTel's
// concern, propagated by the observability interceptors, not here.
//
// identity-svc requires x-tenant-id to set the Postgres `app.current_org_id`
// GUC for RLS. Without it, every multi-tenant SQL query returns "missing
// tenant; cannot run SQL" via the platform db helper.
func ContextWithBearer(ctx context.Context, bearer string) context.Context {
	pairs := []string{}
	if bearer != "" {
		pairs = append(pairs, AuthorizationKey, bearer)
	}
	if c, ok := auth.ClaimsFromContext(ctx); ok {
		if c.OrgID != "" {
			pairs = append(pairs, auth.HeaderTenantID, c.OrgID)
		}
		if c.Subject != "" {
			pairs = append(pairs, auth.HeaderUserID, c.Subject)
		}
		pairs = append(pairs, auth.HeaderActorType, "user")
	}
	if rid := middleware.GetReqID(ctx); rid != "" {
		pairs = append(pairs, auth.HeaderRequestID, rid)
	}
	if len(pairs) == 0 {
		return ctx
	}
	return metadata.AppendToOutgoingContext(ctx, pairs...)
}


